// Rule L27: a division 1.x made of two integer-typed values is written with `float(...)` on its left side.
/// @name DreamShaderTests/Migrate/M_MgIntegerDivide
export void M_MgIntegerDivide(inout material Base)
{
    float Alpha = 0;
    int Seven = 7;
    float Quotient = float(7) / 2;
    Alpha = Quotient + float(Seven) / 2;
    Base.Opacity = Alpha;
}
